import { z } from 'zod';
import { DomainError, notImplemented, type UseCase, type UseCaseContext } from '@agentic-ddd/core';
import { AgentUseCase } from '@agentic-ddd/decorators';
import { TaskCompleted } from '../domain/task.events';
import type { TaskRepository } from '../domain/task.repository';

export const completeTaskInput = z.object({ task_id: z.string().min(1) });
export const completeTaskOutput = z.object({ task_id: z.string(), status: z.literal('completed') });
export type CompleteTaskInput = z.infer<typeof completeTaskInput>;
export type CompleteTaskOutput = z.infer<typeof completeTaskOutput>;

@AgentUseCase({ name: 'complete_task', description: 'Carrega, conclui, salva e publica a tarefa; id ausente falha com TASK_NOT_FOUND.', whenToUse: 'Quando o usuário terminou uma tarefa.', whenNotToUse: 'Para criar uma nova tarefa.', input: completeTaskInput, output: completeTaskOutput, uses: ['method:Task.complete'], emits: [TaskCompleted] })
export class CompleteTask implements UseCase<CompleteTaskInput, CompleteTaskOutput> {
  constructor(private readonly tasks: TaskRepository) {}
  async execute(input: CompleteTaskInput, ctx: UseCaseContext): Promise<CompleteTaskOutput> {
    const task = await this.tasks.findById(input.task_id);
    if (task === null) throw new DomainError('TASK_NOT_FOUND', 'Tarefa não encontrada.');
    task.complete();
    await this.tasks.save(task);
    await ctx.publish(task.pullEvents());
    return { task_id: task.id, status: 'completed' };













  }
}

import { describe, expect, test } from 'bun:test';
import { DomainError, type DomainEvent, type UseCaseContext } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { CompleteTask } from '../application/complete-task';
import { Task } from '../domain/task';
import { TaskCompleted } from '../domain/task.events';
import { InMemoryTaskRepository } from '../infrastructure/in-memory-task.repository';

describe('CompleteTask use-case', () => {
  test(covers(['usecase:complete_task', 'criterion:0001/persistencia-conclusao'], 'conclui tarefa persistida, publica evento e rejeita id ausente'), async () => {
    const tasks = new InMemoryTaskRepository();
    const published: DomainEvent[] = [];
    const ctx: UseCaseContext = {
      correlationId: 'corr-1',
      causationId: 'cause-1',
      async publish(events: readonly DomainEvent[]): Promise<void> { published.push(...events); }
    };
    const task = Task.create('t1', 'Estudar DDD');
    task.pullEvents();
    await tasks.save(task);
    const useCase = new CompleteTask(tasks);

    const output = await useCase.execute({ task_id: 't1' }, ctx);

    expect(output).toEqual({ task_id: 't1', status: 'completed' });
    const persisted = await tasks.findById('t1');
    expect(persisted?.status).toBe('completed');
    expect(published).toHaveLength(1);
    expect(published[0]).toBeInstanceOf(TaskCompleted);
    expect((published[0] as TaskCompleted).payload).toEqual({ taskId: 't1' });

    let error: unknown;
    try {
      await useCase.execute({ task_id: 'missing' }, ctx);
    } catch (caught) {
      error = caught;
    }
    expect(error).toBeInstanceOf(DomainError);
    expect((error as DomainError).code).toBe('TASK_NOT_FOUND');
  });
});
